    # For w=8 (demo 2): gap_start=2, gap_end=4 (cols 2-3 are gap)
    # 
    # Actually I need to calculate corner_fill_range based on w
    # Use: left_fill = (w + 1) // 2 - 2, right_start = (w + 1) // 2 + 1

    left_fill = (w + 1) // 2 - 2
    right_start = (w + 1) // 2 + 1

    # Top-left fill
    if grid[0][0] != bg:
        for r in range(gap_row):
            for c in range(left_fill):
                if r % 2 == 0:  # even y -> all even x
                    if c % 2 == 0:
                        out[r][c] = grid[0][0]
                else:  # odd y -> all odd x
                    if c % 2 == 1:
                        out[r][c] = grid[0][0]

    # Bottom-left fill
    if grid[h-1][0] != bg:
        for r in range(gap_row, h):
            for c in range(left_fill):
                if (r - gap_row) % 2 == 0:
                    if c % 2 == 0:
                        out[r][c] = grid[h-1][0]
                else:
                    if c % 2 == 1:
                        out[r][c] = grid[h-1][0]

    # Top-right fill (only if not background)
    if grid[0][w-1] != bg:
        for r in range(gap_row):
            for c in range(right_start, w):
                if r % 2 == 0:
                    if c % 2 == 0:
                        out[r][c] = grid[0][w-1]
                else:
                    if c % 2 == 1:
                        out[r][c] = grid[0][w-1]

    # Bottom-right fill
    if grid[h-1][w-1] != bg:
        for r in range(gap_row, h):
            for c in range(right_start, w):
                if (r - gap_row) % 2 == 0:
                    if c % 2 == 0:
                        out[r][c] = grid[h-1][w-1]
                else:
                    if c % 2 == 1:
                        out[r][c] = grid[h-1][w-1]

    return out
